const assetModuleURL=import.meta.url;
import {PLAYER_RECOVERY_SHA} from './pins.mjs';
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function loadSelectedPlayerFrames({fetcher=fetch,decode=async b=>createImageBitmap(new Blob([b]))}={}){const base=new URL('./',assetModuleURL),raw=async path=>{const r=await fetcher(new URL(path,base));if(!r.ok)throw Error('PLAYER_INPUT_MISSING');return new Uint8Array(await r.arrayBuffer()).slice()},b=await raw('PLAYER_FRAME_RECOVERY.json');if(await sha(b)!==PLAYER_RECOVERY_SHA)throw Error('PLAYER_PROVENANCE_MISMATCH');const m=JSON.parse(new TextDecoder().decode(b)),images=[],closed=new WeakSet(),dispose=()=>{let first;for(const im of images)if(!closed.has(im)){closed.add(im);try{im.close?.()}catch(e){first??=e}}if(first)throw first};try{const actors={};for(const r of m.frames){const bytes=await raw(r.path);if(await sha(bytes)!==r.sha256)throw Error('PLAYER_FRAME_SHA_MISMATCH');const im=await decode(bytes);images.push(im);if(im.width!==107||im.height!==107)throw Error('PLAYER_FRAME_DIMENSION');actors['actor:'+r.frame]=im}return{actors,provenance:m,dispose}}catch(e){try{dispose()}catch{}throw e}}
